export const SIZE = 15;
export const CENTER = 7;
export type Grid = string[][];
export type Direction = 'across' | 'down';
export interface Point {
  row: number;
  column: number;
}
export interface Tile extends Point {
  letter: string;
}
export interface Position extends Point {
  direction: Direction;
}
export interface Word extends Position {
  word: string;
}
export const PREMIUMS = [
  '# . . + . . . # . . . + . . #',
  '. * . . . ^ . . . ^ . . . * .',
  '. . * . . . + . + . . . * . .',
  '+ . . * . . . + . . . * . . +',
  '. . . . * . . . . . * . . . .',
  '. ^ . . . ^ . . . ^ . . . ^ .',
  '. . + . . . + . + . . . + . .',
  '# . . + . . . * . . . + . . #',
  '. . + . . . + . + . . . + . .',
  '. ^ . . . ^ . . . ^ . . . ^ .',
  '. . . . * . . . . . * . . . .',
  '+ . . * . . . + . . . * . . +',
  '. . * . . . + . + . . . * . .',
  '. * . . . ^ . . . ^ . . . * .',
  '# . . + . . . # . . . + . . #',
].map((line) => line.split(' '));
export const inside = (r: number, c: number) => r >= 0 && r < SIZE && c >= 0 && c < SIZE;
export const occupied = (grid: Grid, r: number, c: number) => inside(r, c) && grid[r][c] !== '.';
export const square = (r: number, c: number) => String.fromCharCode(65 + c) + (r + 1);
export const position = (r: number, c: number, dir: Direction) =>
  dir === 'across' ? r + 1 + String.fromCharCode(65 + c) : square(r, c);
export const empty = (): Grid => Array.from({ length: SIZE }, () => Array(SIZE).fill('.'));
export const clone = (grid: Grid) => grid.map((row) => row.slice());
export const transpose = (grid: Grid) =>
  Array.from({ length: SIZE }, (_, row) => grid.map((line) => line[row]));
export const transposeTiles = (tiles: Tile[]) =>
  tiles.map((tile) => ({ ...tile, row: tile.column, column: tile.row }));
export function parsePosition(text: string): Position | null {
  let m = /^([1-9]|1[0-5])([A-O])$/.exec(text);
  if (m) return { row: Number(m[1]) - 1, column: m[2].charCodeAt(0) - 65, direction: 'across' };
  m = /^([A-O])([1-9]|1[0-5])$/.exec(text);
  return m ? { row: Number(m[2]) - 1, column: m[1].charCodeAt(0) - 65, direction: 'down' } : null;
}
export function tiles(grid: Grid) {
  const result: Tile[] = [];
  for (let row = 0; row < SIZE; row++) {
    for (let column = 0; column < SIZE; column++) {
      if (grid[row][column] !== '.') result.push({ row, column, letter: grid[row][column] });
    }
  }
  return result;
}
export const adjacent = (grid: Grid, r: number, c: number) =>
  [
    [-1, 0],
    [1, 0],
    [0, -1],
    [0, 1],
  ].some(([dr, dc]) => occupied(grid, r + dr, c + dc));
export function connected(grid: Grid) {
  const placed = tiles(grid);
  if (!placed.length) return true;
  const queue: Point[] = [placed[0]];
  const seen = new Set([placed[0].row * SIZE + placed[0].column]);
  for (let i = 0; i < queue.length; i++) {
    for (const [dr, dc] of [
      [-1, 0],
      [1, 0],
      [0, -1],
      [0, 1],
    ]) {
      const row = queue[i].row + dr;
      const column = queue[i].column + dc;
      const key = row * SIZE + column;
      if (occupied(grid, row, column) && !seen.has(key)) {
        seen.add(key);
        queue.push({ row, column });
      }
    }
  }
  return seen.size === placed.length;
}
export function words(grid: Grid) {
  const result: Word[] = [];
  for (const direction of ['across', 'down'] as const) {
    const oriented = direction === 'across' ? grid : transpose(grid);
    for (let row = 0; row < SIZE; row++) {
      let column = 0;
      while (column < SIZE) {
        if (oriented[row][column] === '.') {
          column++;
          continue;
        }
        const start = column;
        let word = '';
        while (column < SIZE && oriented[row][column] !== '.') word += oriented[row][column++];
        if (word.length >= 2) {
          result.push(
            direction === 'across'
              ? { row, column: start, direction, word }
              : { row: start, column: row, direction, word },
          );
        }
      }
    }
  }
  return result;
}
export function display(grid: Grid) {
  const lines = [
    '   ' + Array.from({ length: SIZE }, (_, i) => String.fromCharCode(65 + i)).join(' '),
  ];
  for (let r = 0; r < SIZE; r++) {
    lines.push(
      String(r + 1).padStart(2) +
        ' ' +
        grid[r].map((letter, c) => (letter === '.' ? PREMIUMS[r][c] : letter)).join(' '),
    );
  }
  return lines;
}

export interface Node {
  children: Map<string, Node>;
  terminal: boolean;
}
const makeNode = (): Node => ({ children: new Map<string, Node>(), terminal: false });
export class Trie {
  root = makeNode();
  nodes = 1;
  words = 0;
  add(word: string) {
    let node = this.root;
    for (const letter of word) {
      let child = node.children.get(letter);
      if (!child) {
        child = makeNode();
        node.children.set(letter, child);
        this.nodes++;
      }
      node = child;
    }
    if (node.terminal) return false;
    node.terminal = true;
    this.words++;
    return true;
  }
  find(prefix: string): Node | null {
    let node = this.root;
    for (const letter of prefix) {
      const child = node.children.get(letter);
      if (!child) return null;
      node = child;
    }
    return node;
  }
  has(word: string) {
    return this.find(word)?.terminal ?? false;
  }
  anagrams(rack: string) {
    const counts = new Map<string, number>();
    const result: string[] = [];
    for (const tile of rack) counts.set(tile, (counts.get(tile) ?? 0) + 1);
    const visit = (node: Node, word: string) => {
      if (node.terminal) result.push(word);
      for (const [letter, child] of node.children) {
        const tile = (counts.get(letter) ?? 0) > 0 ? letter : '?';
        if (!(counts.get(tile) ?? 0)) continue;
        counts.set(tile, counts.get(tile)! - 1);
        visit(child, word + letter);
        counts.set(tile, counts.get(tile)! + 1);
      }
    };
    visit(this.root, '');
    return result;
  }
}

import type { Table } from './scoring.ts';
export class Minstd {
  constructor(private state: number) {}
  next() {
    this.state = (48271 * this.state) % 2147483647;
    return this.state;
  }
}
export function shuffle(bag: string[], random: Minstd) {
  for (let i = bag.length - 1; i >= 1; i--) {
    const j = random.next() % (i + 1);
    [bag[i], bag[j]] = [bag[j], bag[i]];
  }
}
export function makeBag(table: Table, random: Minstd) {
  const bag: string[] = [];
  for (const [letter, tile] of table) for (let i = 0; i < tile.count; i++) bag.push(letter);
  shuffle(bag, random);
  return bag;
}
export function draw(bag: string[], count: number) {
  let tiles = '';
  for (let i = 0; i < count && bag.length; i++) tiles += bag.pop()!;
  return tiles;
}
export function exchange(bag: string[], returned: string, random: Minstd) {
  const drawn = draw(bag, returned.length);
  bag.push(...Array.from(returned).sort());
  shuffle(bag, random);
  return drawn;
}
export function value(tiles: string, table: Table) {
  let total = 0;
  for (const tile of tiles) total += table.get(tile)!.value;
  return total;
}

import { readFileSync, mkdirSync, writeFileSync } from 'node:fs';
import * as board from './board.ts';
import type { Grid, Word } from './board.ts';
import { Trie } from './dictionary_trie.ts';
import { generate } from './move_generator.ts';
import * as scoring from './scoring.ts';
import type { Table, ScoredMove } from './scoring.ts';
import * as game from './game.ts';

type Strategy = 'score' | 'tiles' | 'equity';
type JobKind = 'TOPN' | 'VALIDATE' | 'GAME' | 'DUPLICATE';
interface Job {
  kind: JobKind;
  name: string;
  args: string[];
  body: string[];
}
interface Player {
  name: string;
  strategy: Strategy;
  threshold: number;
  index: number;
}
interface TopSettings {
  kind: 'TOPN';
  grid: Grid;
  rack: string;
  count: number;
  strategy: Strategy;
}
interface ValidationSettings {
  kind: 'VALIDATE';
  grid: Grid;
  records: string[];
}
interface GameSettings {
  kind: 'GAME' | 'DUPLICATE';
  players: Player[];
  seed: number;
}
type Checked<T> = { error: string } | T;
interface LegalMove extends ScoredMove {
  leave: string;
  leaveValue: number;
  rank: number;
}
interface PlayerTotals {
  moves: number;
  valid: number;
  score: number;
  loss: number;
}
interface GamePlayer extends Player {
  rack: string;
  score: number;
  plays: number;
  bingos: number;
  exchanges: number;
  passes: number;
  top: number;
  loss: number;
  adjustment: number;
  total: number;
}
const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
const VOWELS = 'AEIOU';
const ascii = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);
const collection = (tiles: string) => Array.from(tiles).sort().join('') || '-';
const nameValid = (name: string) => /^[a-z0-9_]{1,20}$/.test(name);
const rackValid = (rack: string) => /^[A-Z?]{1,7}$/.test(rack);
const numberValid = (text: string, low: number, high: number) =>
  /^(0|[1-9][0-9]*)$/.test(text) && Number(text) >= low && Number(text) <= high;
const strategyValid = (text: string): text is Strategy =>
  text === 'score' || text === 'tiles' || text === 'equity';
const readLines = (path: string) => readFileSync(path, 'ascii').split('\n').slice(0, -1);
const notation = (move: Word) =>
  board.position(move.row, move.column, move.direction) + ' ' + move.word;
const wordList = (move: ScoredMove) =>
  move.words.map((word) => `${word.word}:${word.score}`).join(',');
function frequencies(tiles: string) {
  const counts = new Map<string, number>();
  for (const tile of tiles) counts.set(tile, (counts.get(tile) ?? 0) + 1);
  return counts;
}
function readInput() {
  const table: Table = new Map();
  for (const line of readLines('input/tiles.txt')) {
    if (!line || line.startsWith('#')) continue;
    const [letter, value, count, weight] = line.split(' ');
    table.set(letter, { value: Number(value), count: Number(count), weight: Number(weight) });
  }
  const trie = new Trie();
  const stats = { lines: 0, skipped: 0, duplicates: 0, lengths: new Map<number, number>() };
  for (const line of readLines('input/dictionary.txt')) {
    if (!line || line.startsWith('#')) continue;
    stats.lines++;
    if (!/^[A-Z]{2,15}$/.test(line)) stats.skipped++;
    else if (!trie.add(line)) stats.duplicates++;
    else stats.lengths.set(line.length, (stats.lengths.get(line.length) ?? 0) + 1);
  }
  const lines = readLines('input/jobs.txt');
  const jobs: Job[] = [];
  for (let i = 0; i < lines.length; i++) {
    if (!lines[i] || lines[i].startsWith('#')) continue;
    const [raw, name, ...args] = lines[i].split(' ');
    const kind: JobKind =
      raw === 'TOPN' ? raw : raw === 'VALIDATE' ? raw : raw === 'GAME' ? raw : 'DUPLICATE';
    const body: string[] = [];
    while (lines[++i] !== 'END') body.push(lines[i]);
    jobs.push({ kind, name, args, body });
  }
  return { table, trie, stats, jobs };
}
function usedTiles(grid: Grid, rack: string) {
  return frequencies(
    board
      .tiles(grid)
      .map((t) => scoring.tileKind(t.letter))
      .join('') + rack,
  );
}
function tileCountError(grid: Grid, rack: string, table: Table) {
  const used = usedTiles(grid, rack);
  for (const [letter, tile] of table) {
    if ((used.get(letter) ?? 0) > tile.count) return `too many ${letter}`;
  }
  return null;
}
function unseenTiles(grid: Grid, rack: string, table: Table) {
  const used = usedTiles(grid, rack);
  let unseen = '';
  for (const [letter, tile] of table) unseen += letter.repeat(tile.count - (used.get(letter) ?? 0));
  return unseen;
}
function checkBoard(
  lines: string[],
  rack: string,
  table: Table,
  trie: Trie,
): Checked<{ grid: Grid }> {
  if (lines.length !== board.SIZE) return { error: `board rows ${lines.length}` };
  for (let i = 0; i < lines.length; i++) {
    if (!/^[.A-Za-z]{15}$/.test(lines[i])) return { error: `bad board row ${i + 1}` };
  }
  const grid = lines.map((line) => Array.from(line));
  const error = tileCountError(grid, rack, table);
  if (error) return { error };
  if (board.tiles(grid).length && grid[board.CENTER][board.CENTER] === '.') {
    return { error: 'center empty' };
  }
  if (!board.connected(grid)) return { error: 'disconnected' };
  for (const word of board.words(grid)) {
    if (!trie.has(word.word.toUpperCase())) {
      return {
        error: `unknown word ${word.word} at ${board.position(word.row, word.column, word.direction)}`,
      };
    }
  }
  return { grid };
}
function checkJob(
  job: Job,
  duplicate: boolean,
  table: Table,
  trie: Trie,
): Checked<TopSettings | ValidationSettings | GameSettings> {
  if (!nameValid(job.name)) return { error: 'bad name' };
  if (duplicate) return { error: 'duplicate name' };
  if (job.kind === 'TOPN') {
    if (!numberValid(job.args[0], 1, 99)) return { error: 'bad count' };
    const strategy = job.args[1];
    if (!strategyValid(strategy)) return { error: 'bad order' };
    const rack = job.body[0].split(' ')[1];
    if (!rackValid(rack)) return { error: 'bad rack' };
    const checked = checkBoard(job.body.slice(2), rack, table, trie);
    return 'error' in checked
      ? checked
      : { kind: 'TOPN', ...checked, rack, count: Number(job.args[0]), strategy };
  }
  if (job.kind === 'VALIDATE') {
    let at = 1;
    while (at < job.body.length && !job.body[at].startsWith('MOVE')) at++;
    const checked = checkBoard(job.body.slice(1, at), '', table, trie);
    return 'error' in checked
      ? checked
      : { kind: 'VALIDATE', ...checked, records: job.body.slice(at) };
  }
  if (!numberValid(job.args[0], 1, 2147483646)) return { error: 'bad seed' };
  if (job.body.length < 2 || job.body.length > 4) {
    return { error: `bad player count ${job.body.length}` };
  }
  const players: Player[] = [];
  const names = new Set<string>();
  for (let i = 0; i < job.body.length; i++) {
    const [, name, strategy, threshold] = job.body[i].split(' ');
    if (
      !nameValid(name) ||
      !strategyValid(strategy) ||
      (job.kind === 'GAME' && !numberValid(threshold, 0, 99))
    ) {
      return { error: `bad player ${i + 1}` };
    }
    if (names.has(name)) return { error: `duplicate player ${i + 1}` };
    names.add(name);
    players.push({
      name,
      strategy,
      threshold: job.kind === 'GAME' ? Number(threshold) : 0,
      index: i,
    });
  }
  return { kind: job.kind, players, seed: Number(job.args[0]) };
}
function leaveValue(tiles: string, table: Table) {
  const counts = frequencies(tiles);
  let value = 0;
  let duplicates = 0;
  let vowels = 0;
  let consonants = 0;
  for (const tile of tiles) {
    value += table.get(tile)!.weight;
    if (VOWELS.includes(tile)) vowels++;
    else if (tile !== '?') consonants++;
  }
  for (const [tile, count] of counts) if (tile !== '?') duplicates += count - 1;
  return value - 4 * duplicates - 3 * Math.max(0, Math.abs(vowels - consonants) - 1);
}
function bestLeave(rack: string, table: Table) {
  const counts = frequencies(rack);
  const letters = [...counts.keys()].sort();
  let best = { tiles: '', value: 0 };
  const visit = (index: number, tiles: string) => {
    if (tiles.length >= rack.length) return;
    if (index === letters.length) {
      const value = leaveValue(tiles, table);
      if (
        value > best.value ||
        (value === best.value &&
          (tiles.length > best.tiles.length ||
            (tiles.length === best.tiles.length && tiles < best.tiles)))
      ) {
        best = { tiles, value };
      }
      return;
    }
    const letter = letters[index];
    for (let n = 0; n <= counts.get(letter)!; n++) visit(index + 1, tiles + letter.repeat(n));
  };
  visit(0, '');
  return best;
}
function removeTiles(rack: string, used: Iterable<string>) {
  const left = Array.from(rack);
  for (const tile of used) left.splice(left.indexOf(tile), 1);
  return left.join('');
}
function standardOrder(a: LegalMove, b: LegalMove) {
  return (
    b.score - a.score ||
    a.row - b.row ||
    a.column - b.column ||
    (a.direction === b.direction ? 0 : a.direction === 'across' ? -1 : 1) ||
    ascii(a.word, b.word)
  );
}
function strategyOrder(moves: LegalMove[], strategy: Strategy) {
  return moves
    .slice()
    .sort(
      (a, b) =>
        (strategy === 'tiles'
          ? b.tiles.length - a.tiles.length
          : strategy === 'equity'
            ? b.score + b.leaveValue - (a.score + a.leaveValue)
            : 0) || standardOrder(a, b),
    );
}
function legalMoves(grid: Grid, rack: string, trie: Trie, table: Table) {
  const generated = generate(grid, rack, trie);
  const moves = generated.moves
    .map((move): LegalMove => {
      const result = scoring.score(grid, move, table);
      const leave = removeTiles(
        rack,
        result.tiles.map((t) => scoring.tileKind(t.letter)),
      );
      return { ...result, leave, leaveValue: leaveValue(leave, table), rank: 0 };
    })
    .sort(standardOrder);
  moves.forEach((move, i) => (move.rank = i + 1));
  return { ...generated, moves };
}
function place(grid: Grid, move: Pick<ScoredMove, 'tiles'>) {
  for (const tile of move.tiles) grid[tile.row][tile.column] = tile.letter;
}
function placementKey(move: Pick<ScoredMove, 'tiles'>) {
  return move.tiles
    .slice()
    .sort((a, b) => a.row - b.row || a.column - b.column)
    .map((t) => `${t.row * board.SIZE + t.column}:${t.letter}`)
    .join(',');
}
function positionSummary(grid: Grid) {
  const tiles = board.tiles(grid);
  const words = board.words(grid);
  const premiums = new Map([
    ['#', 0],
    ['*', 0],
    ['^', 0],
    ['+', 0],
  ]);
  let longest = '-';
  let blanks = 0;
  for (const word of words) {
    if (longest === '-' || word.word.length > longest.length) longest = word.word;
  }
  for (const tile of tiles) {
    if (scoring.tileKind(tile.letter) === '?') blanks++;
    const p = board.PREMIUMS[tile.row][tile.column];
    if (premiums.has(p)) premiums.set(p, premiums.get(p)! + 1);
  }
  return `position tiles=${tiles.length} words=${words.length} longest=${longest} blanks=${blanks} premiums=TW:${premiums.get('#')},DW:${premiums.get('*')},TL:${premiums.get('^')},DL:${premiums.get('+')}`;
}
function topJob(job: Job, settings: TopSettings, trie: Trie, table: Table) {
  const { grid, rack, count, strategy } = settings;
  const generated = legalMoves(grid, rack, trie, table);
  const { moves } = generated;
  const unseen = unseenTiles(grid, rack, table);
  let vowels = 0;
  let consonants = 0;
  let blanks = 0;
  for (const tile of rack) {
    if (VOWELS.includes(tile)) vowels++;
    else if (tile === '?') blanks++;
    else consonants++;
  }
  const across = moves.filter((m) => m.direction === 'across').length;
  const bingos = moves.filter((m) => m.tiles.length === scoring.RACK_SIZE).length;
  const withBlank = moves.filter((m) =>
    m.tiles.some((t) => scoring.tileKind(t.letter) === '?'),
  ).length;
  const bestByTiles: (number | null)[] = Array(8).fill(null);
  for (const move of moves) {
    const old = bestByTiles[move.tiles.length];
    if (old === null || move.score > old) bestByTiles[move.tiles.length] = move.score;
  }
  const keep = bestLeave(rack, table);
  const anagrams = trie.anagrams(rack).sort((a, b) => b.length - a.length || ascii(a, b));
  const lines = [
    `TOPN ${job.name} n=${count} order=${strategy} rack=${collection(rack)}`,
    `board tiles=${board.tiles(grid).length} anchors=${generated.anchors}`,
    `unseen count=${unseen.length} tiles=${collection(unseen)}`,
    `rack vowels=${vowels} consonants=${consonants} blanks=${blanks} value=${game.value(rack, table)}`,
    `checks across=${generated.across.join(',')} down=${generated.down.join(',')}`,
    `moves total=${moves.length} across=${across} down=${moves.length - across} bingos=${bingos} blanks=${withBlank}`,
    'best_by_tiles ' +
      Array.from({ length: 7 }, (_, i) => `${i + 1}=${bestByTiles[i + 1] ?? '-'}`).join(' '),
    `exchange keep=${collection(keep.tiles)} value=${keep.value}`,
    `anagrams total=${anagrams.length} top=${anagrams.slice(0, 10).join(',') || '-'}`,
  ];
  for (const word of board.words(grid)) {
    if (word.word.length >= 3) {
      const upper = word.word.toUpperCase();
      let front = '';
      let back = '';
      for (const letter of ALPHABET) {
        if (trie.has(letter + upper)) front += letter;
        if (trie.has(upper + letter)) back += letter;
      }
      if (front || back) {
        lines.push(
          `hook ${board.position(word.row, word.column, word.direction)} ${word.word} front=${front || '-'} back=${back || '-'}`,
        );
      }
    }
  }
  const shown = strategyOrder(moves, strategy).slice(0, count);
  const endgame = unseen.length >= 1 && unseen.length <= 7 && shown.length > 0;
  const nets: number[] = [];
  if (endgame) {
    let best = 0;
    for (let i = 0; i < shown.length; i++) {
      const after = board.clone(grid);
      place(after, shown[i]);
      const replies = legalMoves(after, unseen, trie, table).moves;
      nets.push(shown[i].score - (replies.length ? replies[0].score : 0));
      if (nets[i] > nets[best]) best = i;
    }
    lines.push(`endgame opponent=${collection(unseen)} best=${best + 1} net=${nets[best]}`);
  }
  shown.forEach((move, i) =>
    lines.push(
      `${i + 1} ${notation(move)} score=${move.score} tiles=${move.tiles.length} leave=${collection(move.leave)} value=${move.leaveValue}` +
        (endgame ? ` net=${nets[i]}` : '') +
        ` words=${wordList(move)}`,
    ),
  );
  return { lines, moves: moves.length, bingos };
}
type RecordResult = Checked<{ kind: 'pass' | 'exchange' } | { kind: 'play'; move: ScoredMove }>;
function checkRecord(grid: Grid, fields: string[], trie: Trie, table: Table): RecordResult {
  const [, player, rack, ...action] = fields;
  if (!nameValid(player)) return { error: 'bad player' };
  if (!rackValid(rack)) return { error: 'bad rack' };
  const countError = tileCountError(grid, rack, table);
  if (countError) return { error: countError };
  if (action.length === 1 && action[0] === 'PASS') return { kind: 'pass' };
  if (action[0] === 'EXCHANGE') {
    if (!rackValid(action[1])) return { error: 'bad exchange' };
    const returned = frequencies(action[1]);
    const available = frequencies(rack);
    for (const tile of action[1]) {
      if (returned.get(tile)! > (available.get(tile) ?? 0)) return { error: `rack lacks ${tile}` };
    }
    return { kind: 'exchange' };
  }
  const start = board.parsePosition(action[0]);
  if (!start) return { error: 'bad position' };
  if (!/^[A-Za-z]{2,15}$/.test(action[1])) return { error: 'bad word' };
  const move = { ...start, word: action[1] };
  const squares = scoring.squares(move);
  if (squares.some((t) => !board.inside(t.row, t.column))) return { error: 'off board' };
  for (const tile of squares) {
    if (
      board.occupied(grid, tile.row, tile.column) &&
      grid[tile.row][tile.column] !== tile.letter
    ) {
      return { error: `mismatch at ${board.square(tile.row, tile.column)}` };
    }
  }
  const dr = move.direction === 'down' ? 1 : 0;
  const dc = move.direction === 'across' ? 1 : 0;
  if (
    board.occupied(grid, move.row - dr, move.column - dc) ||
    board.occupied(grid, move.row + dr * move.word.length, move.column + dc * move.word.length)
  ) {
    return { error: 'not whole word' };
  }
  const newTiles = squares.filter((t) => !board.occupied(grid, t.row, t.column));
  if (!newTiles.length) return { error: 'no new tiles' };
  const available = frequencies(rack);
  for (const tile of newTiles) {
    const letter = scoring.tileKind(tile.letter);
    if (!(available.get(letter) ?? 0)) return { error: `rack lacks ${letter}` };
    available.set(letter, available.get(letter)! - 1);
  }
  if (!board.tiles(grid).length) {
    if (!newTiles.some((t) => t.row === board.CENTER && t.column === board.CENTER)) {
      return { error: 'center not covered' };
    }
  } else if (!newTiles.some((t) => board.adjacent(grid, t.row, t.column))) {
    return { error: 'not connected' };
  }
  const result = scoring.score(grid, move, table);
  for (const word of result.words) {
    if (!trie.has(word.word.toUpperCase())) {
      return {
        error: `unknown word ${word.word} at ${board.position(word.row, word.column, word.direction)}`,
      };
    }
  }
  return { kind: 'play', move: result };
}
function validationJob(job: Job, settings: ValidationSettings, trie: Trie, table: Table) {
  const { grid, records } = settings;
  const players = new Map<string, PlayerTotals>();
  const total = { valid: 0, invalid: 0, score: 0, best: 0, loss: 0 };
  const lines = [`VALIDATE ${job.name}`];
  for (let i = 0; i < records.length; i++) {
    const fields = records[i].split(' ');
    const [, name, rack, ...action] = fields;
    const prefix = `move ${i + 1} ${name} ${action.join(' ')}`;
    const checked = checkRecord(grid, fields, trie, table);
    if (!('error' in checked) || checked.error !== 'bad player') {
      if (!players.has(name)) players.set(name, { moves: 0, valid: 0, score: 0, loss: 0 });
      players.get(name)!.moves++;
    }
    if ('error' in checked) {
      total.invalid++;
      lines.push(prefix + ' invalid ' + checked.error);
      continue;
    }
    const moves = legalMoves(grid, rack, trie, table).moves;
    const best = moves.length ? moves[0].score : 0;
    const score = checked.kind === 'play' ? checked.move.score : 0;
    const loss = best - score;
    const player = players.get(name)!;
    player.valid++;
    player.score += score;
    player.loss += loss;
    total.valid++;
    total.score += score;
    total.best += best;
    total.loss += loss;
    if (checked.kind === 'play') {
      const key = placementKey(checked.move);
      const equivalent = moves.find((move) => placementKey(move) === key)!;
      lines.push(
        prefix +
          ` score=${score} total=${player.score} tiles=${checked.move.tiles.length} rank=${equivalent.rank}/${moves.length} best=${best} words=${wordList(checked.move)}`,
      );
      place(grid, checked.move);
    } else lines.push(prefix + ` score=0 total=${player.score} moves=${moves.length} best=${best}`);
  }
  for (const [name, p] of players) {
    lines.push(`player ${name} moves=${p.moves} valid=${p.valid} score=${p.score} loss=${p.loss}`);
  }
  lines.push(
    `total valid=${total.valid} invalid=${total.invalid} score=${total.score} best=${total.best} loss=${total.loss}`,
    positionSummary(grid),
    ...board.display(grid),
  );
  return { lines, moves: records.length, ...total };
}
function gameJob(job: Job, settings: GameSettings, trie: Trie, table: Table) {
  const random = new game.Minstd(settings.seed);
  const bag = game.makeBag(table, random);
  const grid = board.empty();
  const players: GamePlayer[] = settings.players.map((p) => ({
    ...p,
    rack: game.draw(bag, scoring.RACK_SIZE),
    score: 0,
    plays: 0,
    bingos: 0,
    exchanges: 0,
    passes: 0,
    top: 0,
    loss: 0,
    adjustment: 0,
    total: 0,
  }));
  const lines = [`GAME ${job.name} seed=${settings.seed} players=${players.length}`];
  players.forEach((p, i) =>
    lines.push(`player ${i + 1} ${p.name} strategy=${p.strategy} threshold=${p.threshold}`),
  );
  let turns = 0;
  let scoreless = 0;
  let reason: 'out' | 'scoreless' | null = null;
  let wentOut: GamePlayer | null = null;
  let highlight: { turn: number; player: string; move: LegalMove } | null = null;
  while (reason === null) {
    const player = players[turns % players.length];
    turns++;
    const moves = legalMoves(grid, player.rack, trie, table).moves;
    const candidate = strategyOrder(moves, player.strategy)[0];
    const prefix = `turn ${turns} ${player.name} rack=${collection(player.rack)} moves=${moves.length}`;
    if (candidate && !(candidate.score < player.threshold && bag.length >= scoring.RACK_SIZE)) {
      place(grid, candidate);
      player.score += candidate.score;
      player.plays++;
      if (candidate.tiles.length === scoring.RACK_SIZE) player.bingos++;
      player.top = Math.max(player.top, candidate.score);
      player.loss += moves[0].score - candidate.score;
      player.rack = candidate.leave;
      const drawn = game.draw(bag, scoring.RACK_SIZE - player.rack.length);
      player.rack += drawn;
      scoreless = 0;
      lines.push(
        prefix +
          ` best=${moves[0].score} play ${notation(candidate)} score=${candidate.score} total=${player.score} draw=${collection(drawn)} bag=${bag.length}`,
      );
      if (highlight === null || candidate.score > highlight.move.score) {
        highlight = { turn: turns, player: player.name, move: candidate };
      }
      if (!player.rack.length && !bag.length) {
        reason = 'out';
        wentOut = player;
      }
    } else if (bag.length >= scoring.RACK_SIZE) {
      const keep = bestLeave(player.rack, table).tiles;
      const returned = removeTiles(player.rack, keep);
      const drawn = game.exchange(bag, returned, random);
      player.rack = keep + drawn;
      player.exchanges++;
      scoreless++;
      lines.push(
        prefix + ` exchange keep=${collection(keep)} draw=${collection(drawn)} bag=${bag.length}`,
      );
    } else {
      player.passes++;
      scoreless++;
      lines.push(prefix + ` pass bag=${bag.length}`);
    }
    if (reason === null && scoreless === 6) reason = 'scoreless';
  }
  lines.push(
    reason === 'out'
      ? `end reason=out player=${wentOut!.name} turns=${turns}`
      : `end reason=scoreless turns=${turns}`,
  );
  let transferred = 0;
  for (const p of players) {
    p.adjustment = -game.value(p.rack, table);
    if (p !== wentOut) transferred -= p.adjustment;
  }
  if (wentOut) wentOut.adjustment = transferred;
  for (const p of players) {
    p.total = p.score + p.adjustment;
    lines.push(
      `final ${p.name} score=${p.score} rack=${collection(p.rack)} adjust=${p.adjustment > 0 ? '+' : ''}${p.adjustment} total=${p.total}`,
    );
  }
  const standings = players.slice().sort((a, b) => b.total - a.total || a.index - b.index);
  standings.forEach((p, i) =>
    lines.push(
      `standing ${i + 1} ${p.name} total=${p.total} plays=${p.plays} bingos=${p.bingos} exchanges=${p.exchanges} passes=${p.passes} top=${p.top} loss=${p.loss}`,
    ),
  );
  lines.push(
    'winner ' +
      players
        .filter((p) => p.total === standings[0].total)
        .map((p) => p.name)
        .join(','),
  );
  if (highlight) {
    lines.push(
      `highlight turn=${highlight.turn} player=${highlight.player} play ${notation(highlight.move)} score=${highlight.move.score}`,
    );
  }
  lines.push(positionSummary(grid), ...board.display(grid));
  const total = { turns, plays: 0, exchanges: 0, passes: 0, bingos: 0 };
  for (const p of players) {
    total.plays += p.plays;
    total.exchanges += p.exchanges;
    total.passes += p.passes;
    total.bingos += p.bingos;
  }
  return { lines, ...total };
}
function duplicateJob(job: Job, settings: GameSettings, trie: Trie, table: Table) {
  const random = new game.Minstd(settings.seed);
  const bag = game.makeBag(table, random);
  const grid = board.empty();
  const players = settings.players.map((p) => ({ ...p, total: 0 }));
  const lines = [`DUPLICATE ${job.name} seed=${settings.seed} players=${players.length}`];
  players.forEach((p, i) => lines.push(`player ${i + 1} ${p.name} strategy=${p.strategy}`));
  let rack = game.draw(bag, scoring.RACK_SIZE);
  let masterTotal = 0;
  let rounds = 0;
  let reason: 'out' | 'stuck';
  while (true) {
    const moves = legalMoves(grid, rack, trie, table).moves;
    if (!moves.length) {
      reason = 'stuck';
      break;
    }
    rounds++;
    const master = moves[0];
    const picks: number[] = [];
    for (const player of players) {
      const move = strategyOrder(moves, player.strategy)[0];
      player.total += move.score;
      picks.push(move.score);
    }
    masterTotal += master.score;
    lines.push(
      `round ${rounds} rack=${collection(rack)} moves=${moves.length} master ${notation(master)} score=${master.score} picks=${picks.join(',')}`,
    );
    place(grid, master);
    rack = master.leave;
    rack += game.draw(bag, scoring.RACK_SIZE - rack.length);
    if (!rack.length) {
      reason = 'out';
      break;
    }
  }
  lines.push(
    reason === 'out'
      ? `end reason=out rounds=${rounds}`
      : `end reason=stuck rounds=${rounds} rack=${collection(rack)}`,
    `master total=${masterTotal}`,
  );
  for (const player of players) {
    lines.push(
      `final ${player.name} total=${player.total} percent=${masterTotal > 0 ? Math.floor((100 * player.total) / masterTotal) : 0}`,
    );
  }
  const maximum = Math.max(...players.map((p) => p.total));
  lines.push(
    'winner ' +
      players
        .filter((p) => p.total === maximum)
        .map((p) => p.name)
        .join(','),
    positionSummary(grid),
    ...board.display(grid),
  );
  return { lines, rounds };
}
function writeParagraphs(file: string, paragraphs: string[][]) {
  writeFileSync(
    `output/${file}`,
    paragraphs.map((lines) => lines.join('\n')).join('\n\n') + '\n',
    'ascii',
  );
}
function main() {
  const { table, trie, stats, jobs } = readInput();
  const lengths = [...stats.lengths.keys()].sort((a, b) => a - b);
  const moves: string[][] = [
    [
      `DICTIONARY lines=${stats.lines} words=${trie.words} skipped=${stats.skipped} duplicates=${stats.duplicates} nodes=${trie.nodes}`,
      'lengths ' + lengths.map((k) => `${k}=${stats.lengths.get(k)}`).join(' '),
    ],
  ];
  const validation: string[][] = [];
  const games: string[][] = [];
  const topTotal = { jobs: 0, errors: 0, moves: 0, bingos: 0 };
  const validationTotal = { jobs: 0, errors: 0, moves: 0, valid: 0, invalid: 0, loss: 0 };
  const gameTotal = {
    games: 0,
    duplicates: 0,
    errors: 0,
    turns: 0,
    rounds: 0,
    plays: 0,
    exchanges: 0,
    passes: 0,
    bingos: 0,
  };
  const seen = new Set<string>();
  for (const job of jobs) {
    const duplicate = seen.has(job.name);
    seen.add(job.name);
    const settings = checkJob(job, duplicate, table, trie);
    const paragraphs = job.kind === 'TOPN' ? moves : job.kind === 'VALIDATE' ? validation : games;
    if (job.kind === 'TOPN') topTotal.jobs++;
    else if (job.kind === 'VALIDATE') validationTotal.jobs++;
    else if (job.kind === 'GAME') gameTotal.games++;
    else gameTotal.duplicates++;
    if ('error' in settings) {
      if (job.kind === 'TOPN') topTotal.errors++;
      else if (job.kind === 'VALIDATE') validationTotal.errors++;
      else gameTotal.errors++;
      paragraphs.push([`${job.kind} ${job.name}`, 'error ' + settings.error]);
      continue;
    }
    if (settings.kind === 'TOPN') {
      const result = topJob(job, settings, trie, table);
      moves.push(result.lines);
      topTotal.moves += result.moves;
      topTotal.bingos += result.bingos;
    } else if (settings.kind === 'VALIDATE') {
      const result = validationJob(job, settings, trie, table);
      validation.push(result.lines);
      validationTotal.moves += result.moves;
      validationTotal.valid += result.valid;
      validationTotal.invalid += result.invalid;
      validationTotal.loss += result.loss;
    } else if (settings.kind === 'GAME') {
      const result = gameJob(job, settings, trie, table);
      games.push(result.lines);
      gameTotal.turns += result.turns;
      gameTotal.plays += result.plays;
      gameTotal.exchanges += result.exchanges;
      gameTotal.passes += result.passes;
      gameTotal.bingos += result.bingos;
    } else {
      const result = duplicateJob(job, settings, trie, table);
      games.push(result.lines);
      gameTotal.rounds += result.rounds;
    }
  }
  moves.push([
    `SUMMARY jobs=${topTotal.jobs} errors=${topTotal.errors} moves=${topTotal.moves} bingos=${topTotal.bingos}`,
  ]);
  validation.push([
    `SUMMARY jobs=${validationTotal.jobs} errors=${validationTotal.errors} moves=${validationTotal.moves} valid=${validationTotal.valid} invalid=${validationTotal.invalid} loss=${validationTotal.loss}`,
  ]);
  games.push([
    `SUMMARY games=${gameTotal.games} duplicates=${gameTotal.duplicates} errors=${gameTotal.errors} turns=${gameTotal.turns} rounds=${gameTotal.rounds} plays=${gameTotal.plays} exchanges=${gameTotal.exchanges} passes=${gameTotal.passes} bingos=${gameTotal.bingos}`,
  ]);
  mkdirSync('output', { recursive: true });
  writeParagraphs('moves.txt', moves);
  writeParagraphs('validation.txt', validation);
  writeParagraphs('game.txt', games);
}
main();

import * as board from './board.ts';
import type { Grid, Tile, Word } from './board.ts';
import type { Node } from './dictionary_trie.ts';
import { Trie } from './dictionary_trie.ts';
import { crossWord } from './scoring.ts';
export interface Move extends Word {
  tiles: Tile[];
}
const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
export function anchors(grid: Grid) {
  const result = new Set<number>();
  if (!board.tiles(grid).length) result.add(board.CENTER * board.SIZE + board.CENTER);
  else {
    for (let r = 0; r < board.SIZE; r++) {
      for (let c = 0; c < board.SIZE; c++) {
        if (grid[r][c] === '.' && board.adjacent(grid, r, c)) result.add(r * board.SIZE + c);
      }
    }
  }
  return result;
}
export function crossChecks(grid: Grid, trie: Trie) {
  const allowed: (Set<string> | null)[][] = Array.from({ length: board.SIZE }, () =>
    Array(board.SIZE).fill(null),
  );
  let checked = 0;
  let dead = 0;
  let total = 0;
  for (let row = 0; row < board.SIZE; row++) {
    for (let column = 0; column < board.SIZE; column++) {
      if (grid[row][column] !== '.') continue;
      const letters = new Set<string>();
      if (!board.occupied(grid, row - 1, column) && !board.occupied(grid, row + 1, column)) {
        for (const letter of ALPHABET) letters.add(letter);
      } else {
        checked++;
        for (const letter of ALPHABET) {
          if (trie.has(crossWord(grid, { row, column, letter }, 'down').word.toUpperCase())) {
            letters.add(letter);
          }
        }
        if (!letters.size) dead++;
        total += letters.size;
      }
      allowed[row][column] = letters;
    }
  }
  return { allowed, stats: [checked, dead, total] };
}
function acrossMoves(
  grid: Grid,
  rack: string,
  trie: Trie,
  anchorSet: Set<number>,
  checks: ReturnType<typeof crossChecks>,
) {
  const result: Move[] = [];
  const counts = new Map<string, number>();
  for (const tile of rack) counts.set(tile, (counts.get(tile) ?? 0) + 1);
  for (const anchor of anchorSet) {
    const row = Math.floor(anchor / board.SIZE);
    const anchorColumn = anchor % board.SIZE;
    function choices(
      node: Node,
      allowed: Set<string> | null,
      use: (node: Node, letter: string) => void,
    ) {
      for (const letter of [...node.children.keys()].sort()) {
        if (allowed !== null && !allowed.has(letter)) continue;
        for (const tile of [letter, '?']) {
          if (!(counts.get(tile) ?? 0)) continue;
          counts.set(tile, counts.get(tile)! - 1);
          use(node.children.get(letter)!, tile === '?' ? letter.toLowerCase() : letter);
          counts.set(tile, counts.get(tile)! + 1);
        }
      }
    }
    function extend(column: number, node: Node, word: string, start: number, filled: boolean) {
      const occupied = column < board.SIZE && grid[row][column] !== '.';
      if (!occupied && filled && node.terminal) {
        const tiles: Tile[] = [];
        for (let i = 0; i < word.length; i++) {
          if (grid[row][start + i] === '.') tiles.push({ row, column: start + i, letter: word[i] });
        }
        result.push({ row, column: start, direction: 'across', word, tiles });
      }
      if (column >= board.SIZE) return;
      if (occupied) {
        const letter = grid[row][column];
        const child = node.children.get(letter.toUpperCase());
        if (child) extend(column + 1, child, word + letter, start, filled);
      } else {
        choices(node, checks.allowed[row][column], (child, letter) =>
          extend(column + 1, child, word + letter, start, filled || column === anchorColumn),
        );
      }
    }
    if (board.occupied(grid, row, anchorColumn - 1)) {
      let start = anchorColumn - 1;
      while (board.occupied(grid, row, start - 1)) start--;
      const prefix = grid[row].slice(start, anchorColumn).join('');
      const node = trie.find(prefix.toUpperCase());
      if (node) extend(anchorColumn, node, prefix, start, false);
    } else {
      let limit = 0;
      while (
        anchorColumn - limit - 1 >= 0 &&
        grid[row][anchorColumn - limit - 1] === '.' &&
        !anchorSet.has(row * board.SIZE + anchorColumn - limit - 1)
      ) {
        limit++;
      }
      const leftPart = (node: Node, word: string) => {
        extend(anchorColumn, node, word, anchorColumn - word.length, false);
        if (word.length < limit) {
          choices(node, null, (child, letter) => leftPart(child, word + letter));
        }
      };
      leftPart(trie.root, '');
    }
  }
  return result;
}
export function generate(grid: Grid, rack: string, trie: Trie) {
  const anchorSet = anchors(grid);
  const across = crossChecks(grid, trie);
  const transposed = board.transpose(grid);
  const down = crossChecks(transposed, trie);
  const moves = acrossMoves(grid, rack, trie, anchorSet, across);
  for (const move of acrossMoves(transposed, rack, trie, anchors(transposed), down)) {
    const tiles = board.transposeTiles(move.tiles);
    if (
      tiles.length === 1 &&
      (board.occupied(grid, tiles[0].row, tiles[0].column - 1) ||
        board.occupied(grid, tiles[0].row, tiles[0].column + 1))
    ) {
      continue;
    }
    moves.push({ ...move, row: move.column, column: move.row, direction: 'down', tiles });
  }
  return { moves, anchors: anchorSet.size, across: across.stats, down: down.stats };
}

import * as board from './board.ts';
import type { Grid, Tile, Word, Direction } from './board.ts';
export const RACK_SIZE = 7;
export const BINGO = 50;
export interface TileValue {
  value: number;
  count: number;
  weight: number;
}
export type Table = Map<string, TileValue>;
export interface ScoredWord extends Word {
  score: number;
}
export interface ScoredMove extends Word {
  tiles: Tile[];
  words: ScoredWord[];
  score: number;
}
export const tileKind = (letter: string) => (letter >= 'a' && letter <= 'z' ? '?' : letter);
export const squares = (move: Word): Tile[] =>
  Array.from(move.word, (letter, i) => ({
    row: move.row + (move.direction === 'down' ? i : 0),
    column: move.column + (move.direction === 'across' ? i : 0),
    letter,
  }));
export function crossWord(grid: Grid, tile: Tile, direction: Direction): Word {
  const dr = direction === 'down' ? 1 : 0;
  const dc = direction === 'across' ? 1 : 0;
  let row = tile.row;
  let column = tile.column;
  while (board.occupied(grid, row - dr, column - dc)) {
    row -= dr;
    column -= dc;
  }
  const start = { row, column, direction };
  let word = '';
  while (
    board.inside(row, column) &&
    ((row === tile.row && column === tile.column) || board.occupied(grid, row, column))
  ) {
    word += row === tile.row && column === tile.column ? tile.letter : grid[row][column];
    row += dr;
    column += dc;
  }
  return { ...start, word };
}
export function wordScore(grid: Grid, word: Word, table: Table) {
  let total = 0;
  let multiplier = 1;
  for (const tile of squares(word)) {
    let points = table.get(tileKind(tile.letter))!.value;
    if (grid[tile.row][tile.column] === '.') {
      const premium = board.PREMIUMS[tile.row][tile.column];
      if (premium === '+') points *= 2;
      if (premium === '^') points *= 3;
      if (premium === '*') multiplier *= 2;
      if (premium === '#') multiplier *= 3;
    }
    total += points;
  }
  return total * multiplier;
}
export function score(grid: Grid, move: Word, table: Table): ScoredMove {
  const tiles = squares(move).filter((t) => grid[t.row][t.column] === '.');
  const words: Word[] = [
    { row: move.row, column: move.column, direction: move.direction, word: move.word },
  ];
  const perpendicular = move.direction === 'across' ? 'down' : 'across';
  for (const tile of tiles) {
    const cross = crossWord(grid, tile, perpendicular);
    if (cross.word.length >= 2) words.push(cross);
  }
  let total = tiles.length === RACK_SIZE ? BINGO : 0;
  const scored = words.map((word) => {
    const points = wordScore(grid, word, table);
    total += points;
    return { ...word, score: points };
  });
  return { ...move, tiles, words: scored, score: total };
}
